INSERT INTO `mod_lore_codex_entry` (`ID`, `Kind`, `Zone`, `SortOrder`, `Faction`, `RequiredState`, `Title`, `Body`, `Sources`) VALUES
(3300, 0, 33, 0, 0, 0, 'Stranglethorn Vale', 'Stranglethorn Vale is a vast, sweltering jungle at the southern end of the Eastern Kingdoms, running from the borders of Duskwood down to a rugged cape on the Great Sea. It was once the heart of the Gurubashi Empire, and the ruins of troll cities lie everywhere beneath the vines. The old capital, Zul''Gurub, still broods in the northeast, where the blood god Hakkar has been called back into the world. What remains of the Gurubashi has splintered into warring tribes, chief among them the Bloodscalps of the north and the Skullsplitters of the eastern hills. Outsiders have come for the jungle''s riches and dangers alike: big game hunters, Venture Company miners and loggers, a Stormwind expedition gone bad under Colonel Kurzen, and the ogres of the Mosh''Ogg mound. The Horde holds Grom''gol on the western shore. On the southern cape the goblin port of Booty Bay trades with all comers, while Bloodsail pirates prowl its waters and Stranglethorn Fever lurks in the undergrowth.', 'warcraft.wiki.gg/wiki/Stranglethorn_Vale (Gurubashi heart, Zul''Gurub, Hakkar summoned by the Atal''ai, Booty Bay, Venture Co., Kurzen, Grom''gol, Stranglethorn Fever); page_text 144 (Bloodscalps and Skullsplitters as tribal enemies); quest 206 (Mosh''Ogg in the eastern mountains); quest 348 (Stranglethorn Fever); quest 595 (Bloodsails all over southern Stranglethorn); npc_text 7454 (Molthor: Hakkar has been brought back into our world; Molthor is not phased by mod-individual-progression, so this is heard at every state)'),
(3301, 1, 33, 1, 0, 0, 'Rebel Camp', 'Northwest of the road that enters the jungle from Duskwood, a handful of soldiers hold a small camp under Lieutenant Doren. They once marched under Colonel Kurzen and served him with fierce loyalty, until his descent into corruption twisted that loyalty into rage and they broke away. Outnumbered by their former comrades, they live by guile. Sergeant Yohwa plans raids on the compound to the east, Brother Nimetz searches troll legends for the cause of Kurzen''s fall, and supplies, land mines among them, come up from Booty Bay.', 'quest 198 description and reward text (camp northwest of the road from Duskwood, land mines); quest 215 reward text; quests 203, 207; quests 329, 330, 331 (traitor Merle); DB: Rebel Camp NPCs 469, 733, 739, 738, 1421, 1422 stand in area 99'),
(3302, 1, 33, 2, 0, 0, 'Nesingwary''s Expedition', 'Beside a freshwater river inlet in northern Stranglethorn, near old docks left by some forgotten people, the dwarf Hemet Nesingwary pitched the base camp from which he hunted the Vale. His son, Hemet Nesingwary Jr., now keeps the camp in his father''s stead. Ajeck Rouack teaches the hunting of tigers, Sir S. J. Erlgadin the tracking of panthers, and the faithful Barnil Stonepot keeps the camp in order. Strangers are not readily welcomed. Those who prove themselves against the beasts of the jungle may join the hunt, and each test brings a fiercer quarry.', 'page_text 125-126 (base camp by a river inlet, abandoned docks, companions); quest 583 description and reward text; quest 201 (camp upriver of the Venture mining camp); DB: 715, 716, 717, 718 in area 100; creature 715 Hemet Nesingwary Jr. keeps the camp (quest 583)'),
(3303, 1, 33, 3, 0, 0, 'Kurzen''s Compound', 'East of the Rebel Camp stands the fortified compound of Colonel Kurzen''s expedition, whose jungle fighters outnumber the rebels ten to one. Medicine men tend their wounded with jungle remedies and poison their foes with venom fern extract, and wranglers keep tigers and panthers trained as beasts of war. The camp''s logistics officer, Bookie Herod, kept his office on the top floor of its only two-story house. Behind it all a cavern called the Stockpile runs into the hills, where Kurzen''s most highly trained men gather and the colonel commands from deep within.', 'quest 203 description (outnumbers us 10 to 1, camp to the east); quest 204 description (medicine men, remedies, venom fern extracts); quest 200 description (Bookie Herod, two-story house); quests 328, 574, 202 (the Stockpile); DB spawns: Kurzen Wrangler 943, War Tiger 976, War Panther 977 in area 101; warcraft.wiki.gg/wiki/Kurzen''s_Compound (east of Rebel Camp, war beasts trained)'),
(3304, 1, 33, 4, 0, 0, 'Venture Co. Base Camp', 'Near Lake Nazferiti, the goblins of the Venture Company have cut a logging and mining camp out of the jungle. Lumberjacks and shredders fell the trees while geologists hunt the strange blue crystals found in the hills, which the company tumbles and treats, apparently for use as a fuel or catalyst. Foreman Cozzle runs the work from a house at the operations center. The company''s greed has made it enemies, not least among the goblins of Booty Bay, who complain it leaves no room for honest trade.', 'warcraft.wiki.gg/wiki/Stranglethorn_Vale (Venture Co. Base Camp near Lake Nazferiti for logging); quest 213 description and reward text; quest 600 description; DB spawns: Lumberjack 921, Shredder 4260, Geologist 1096 in 1740; Foreman Cozzle 4723 in 1760; quest 1182 description (Cozzle''s house at Lake Nazferiti)'),
(3305, 1, 33, 5, 0, 0, 'Bal''lal Ruins', 'The Bal''lal Ruins and the nearby Tkashi Ruins are crumbling Gurubashi sites in the north of the Vale, held by warriors, axe throwers and shamans of the Bloodscalp tribe, whose territory runs on to the great ruins of Zul''Kunda along the coast. Among the stones of Bal''lal lies an ancient tablet carved with a troll legend called Moon Over the Vale, one of four tablets Brother Nimetz of the Rebel Camp hoped would explain Colonel Kurzen''s madness.', 'quest 207 description (first tablet in the Bal''lal Ruins); gameobject 57 Moon Over the Vale in area 123; quests 9436, 9457 (Nemeth Hawkeye, Farstriders, Naias); DB spawns: Bloodscalp Warrior, Axe Thrower, Shaman in areas 123 and 126'),
(3306, 1, 33, 6, 0, 0, 'Ruins of Zul''Kunda', 'Zul''Kunda is a sprawling troll ruin near the northern coast and the seat of the Bloodscalp tribe. Their chief, Gan''zulah, and his witch doctor, Nezzliok the Dire, rule from deep within, while headhunters stalk Zul''Kunda and the neighboring Zuuldaia Ruins carrying the shrunken heads of their victims. The Bloodscalps are sworn enemies of the Darkspear and wage war on the Skullsplitter tribe. Two ancient tablets stand among the ruins, one telling of the Fall of Gurubashi and the other of the Emperor''s Tomb, relics of the empire that raised these walls.', 'warcraft.wiki.gg/wiki/Ruins_of_Zul''Kunda (very large ruins, Bloodscalp territory, Gan''zulah and Nezzliok); quest 582 description (headhunters at Zuuldaia and Zul''Kunda along the coast); quest 584 (enemies of the Darkspear, deep within Zul''Kunda); quest 585 (Bloodscalps war with the Skullsplitters); quest 207 (third and fourth tablets); gameobjects 52 Fall of Gurubashi and 54 The Emperor''s Tomb in area 102'),
(3307, 1, 33, 7, 0, 0, 'The Vile Reef', 'Off the Savage Coast lie the drowned ruins of an old troll city, sunk beneath the waves when a great shudder of the earth struck long ago. The Darkspear call the place the Vile Reef, for Saltscale murlocs now dwell among its broken stones and attack any who draw near, while giant clams cling to the walls. A tablet in the ruins tells the tale of Gri''lek, a hero of troll legend whose story is sacred to the Darkspear. Deeper among the drowned stones lies a sunken shrine known as the Altar of the Tides.', 'quest 629 description and reward text; quest 207 (second tablet in the Vile Reef); quest 611 description (sunken troll city near the haunted island); gameobjects 58 Gri''lek the Wanderer, 2576 Altar of the Tides, 2744 Giant Clam in area 104; DB spawns: Saltscale murlocs in area 104'),
(3308, 1, 33, 8, 0, 0, 'Grom''gol Base Camp', 'Grom''gol is the Horde''s walled stronghold on the western coast of Stranglethorn. Commander Aggro''gosh holds it for the Warchief, and its first duty is to keep a chain of supply open to Stonard in the Swamp of Sorrows. The Horde did not come to make war on the jungle, but raptors prowl outside the walls and Mosh''Ogg ogres squatting in the nearby Mizjah Ruins ambush its caravans. Zeppelins link the camp to Orgrimmar and the Undercity. Darkspear trolls such as Nimboya and the witch doctor Kin''weelay serve here too, back in the jungle their tribe once called home, though the local tribes count the Darkspear as enemies.', 'quests 568, 569 descriptions; creature subnames 3149 Durotar Zeppelin Master, 12137 Tirisfal Glades Zeppelin Master; quest 581 (Darkspear left with Thrall); warcraft.wiki.gg/wiki/Grom''gol_Base_Camp; quest 584 (Bloodscalps enemies of the Darkspear); DB: Nimboya 2497, Kin''weelay 2519 spawned in area 117'),
(3309, 1, 33, 9, 0, 0, 'Mosh''Ogg Ogre Mound', 'In the eastern mountains of Stranglethorn, not far from Zul''Gurub, the Mosh''Ogg ogres have made their home in a great mound with a cave at its heart. Warmongers, maulers and spellcrafters guard its slopes, and deep inside dwells the ogre mage Mai''Zoth. The clan''s reach spreads beyond the mound, for Mosh''Ogg brutes also squat in the Mizjah Ruins near Grom''gol. The ogres will even gamble with outsiders: a Booty Bay gambler named Maury once won so much from them that he was chased off the mound.', 'quest 206 description (Ogre Mound in the eastern mountains); quest 591 description (deep within the Mosh''Ogg ogre mound); quest 613 description (Maury gambled with the ogres); quest 569 (ogres in Mizjah Ruins); warcraft.wiki.gg/wiki/Mosh''Ogg_Ogre_Mound (just south of Zul''Gurub); DB spawns in areas 105 and 129; warcraft.wiki.gg/wiki/Mosh''Ogg_Ogre_Mound (the ogres inhabit a cave)'),
(3310, 1, 33, 10, 0, 0, 'Ruins of Zul''Mamwe', 'Zul''Mamwe lies in a mountain-ringed valley in the east of the Vale, south of the Mosh''Ogg mound. It is the stronghold of the Skullsplitters, the second great troll tribe of Stranglethorn and bitter rivals of the Bloodscalps. Their chief, Ana''thek the Cruel, holds the ruins with the clan witch doctor Mogh the Undying, whose kind carry the fetishes of the tribe''s dark magic. The Skullsplitters keep piles of trophy skulls here and at the nearby ruins of Balia''mah and Ziata''jai. Strangely, one of Kurzen''s soldiers walks among them too, his mind enslaved by Mogh.', 'warcraft.wiki.gg/wiki/Ruins_of_Zul''Mamwe (south of the Mosh''Ogg mound, mountains on all sides but north, second major tribe, Ana''thek); quest 585 (trophy piles at Balia''mah, Ziata''jai, Zul''Mamwe); quest 205 (Skullsplitter Fetishes from witch doctors and mystics); creature_template 1059, 1060 subnames; DB spawn: Kurzen Mindslave 6366 in area 103; trophy skull gameobjects 2891, 2892, 2893; warcraft.wiki.gg/wiki/Kurzen_Mindslave (in Zul''Mamwe, mind-controlled by Mogh the Undying)'),
(3311, 1, 33, 11, 0, 0, 'Crystalvein Mine', 'Crystalvein Mine is a source of the Singing Crystals, blue stones found only in Stranglethorn and prized by certain buyers. The Venture Company covets the mine but cannot get in, for its tunnels are infested with basilisks, which eat the crystal and draw their hardened hides from it, so the goblins make do with digging in the surrounding hills. Pulsing blue shards cut from the Ironjaw basilisks inside are rare and potent. A Darkspear witch doctor of Grom''gol seeks them, for he believes their magic can bend a powerful relic to his will, and says the shards sing to him.', 'quest 600 description (Venture can''t get into the mine because of the basilisks); quest 605 description (crystals unique to Stranglethorn, basilisks eat the crystal); quest 589 description and reward text (Pulsing Blue Shards, I hear them sing); DB spawns: Ironjaw and Thrashtail Basilisks in area 310'),
(3312, 1, 33, 12, 0, 0, 'Yojamba Isle', 'Off the northwestern coast of the Vale lies Yojamba Isle, where envoys of the Zandalar tribe have made their camp. The Zandalari defeated the blood god Hakkar at Zul''Gurub in ages past, and now that he has risen there again they have returned to Stranglethorn to oppose him, calling on outsiders of every race to help. Servants of King Rastakhan gather here under Molthor, the Hand of Rastakhan, who leads the expedition. They tend the Altar of Zanza and keep a captured Hakkari zealot under guard.', 'warcraft.wiki.gg/wiki/Yojamba_Isle (Zandalar recruited Alliance and Horde against Hakkar); warcraft.wiki.gg/wiki/Stranglethorn_Vale (Zandalari defeated Hakkar at Zul''Gurub); npc_text 7514, 7515 (envoys of Rastakhan); creature 14875 Molthor <Hand of Rastakhan>, 14912 Captured Hakkari Zealot, gameobject 180367 Altar of Zanza in area 3357; npc_text 7720 (Molthor led the expedition from distant islands to Yojamba Isle)'),
(3313, 1, 33, 13, 0, 0, 'Gurubashi Arena', 'North of Booty Bay, in the jungle of the cape, stands a great stone arena raised by the Gurubashi trolls. In ancient days its fights were to the death, and its sand was stained with troll blood. The empire is gone but the bloodletting is not. A pirate called Short John Mithril presides over the sport now. From time to time he leaves a chest of treasure on the arena floor for whoever can claim it, and rivals of every race gather to fight over the prize. Those who triumph again and again are named Grandmaster of the Arena.', 'warcraft.wiki.gg/wiki/Gurubashi_Arena (Gurubashi built it, fights to the death, chest event); creature_text 14508; npc_text 7074; quests 7810, 7838; warcraft.wiki.gg/wiki/Gurubashi_Arena (sand muddy with troll blood in ancient times)'),
(3314, 1, 33, 14, 0, 0, 'Mistvale Valley', 'Mistvale Valley is a jungle valley on the Cape of Stranglethorn, home to great troops of gorillas, from the elder Mistvale apes to their silverback patriarchs. In a hidden cave on the southern cape, called the Spirit Den, lives Witch Doctor Unbagwa. He prizes gorilla fangs and claims the power to call up Mokk the Savage, an elusive white beast whose heart is said to be the only cure for Stranglethorn Fever, provided someone guards him from the angry apes while he works.', 'quest 348 description (only cure is the heart of Mokk the Savage, Unbagwa in a hidden cave on the southern cape); quest 349 reward text (gorilla fangs, protect Unbagwa); DB spawns: Elder Mistvale Gorilla 1557, Silverback Patriarch 1558 in 1737; Unbagwa 1449 in 1742 (Spirit Den)'),
(3315, 1, 33, 15, 0, 0, 'Nek''mani Wellspring', 'High in the cliffs above the Southern Savage Coast, on the western side of the cape, lies a holy spring said to hold the only clean fresh water south of Duskwood. Its sanctity is bitterly disputed: scholars of nearly every race claim its waters were made divine for their own people. Lately an expedition of naga explorers has advanced on the spring and guards it fiercely, and a rarely seen naga, Lord Sakrasis, walks among them. The far seer of Grom''gol counts the water as the final reagent of a powerful enchantment.', 'quest 573 description (Holy Spring, every race claims it, naga explorers); warcraft.wiki.gg/wiki/Nek''mani_Wellspring (only clean freshwater south of Duskwood, cliffs above the Southern Savage Coast); DB spawns: Naga Explorer 1907, Lord Sakrasis 2541 (rare) in area 1738'),
(3316, 1, 33, 16, 0, 0, 'Ruins of Aboraz', 'Northeast of Booty Bay, the ruins of Aboraz and neighboring Jubuwal have become the domain of Zanzil the Outcast. Feared by his own people for his power over the minds of others, Zanzil feeds a mixture of jungle plants to those who fall into his hands, leaving them strong of body and empty of will. Zombies, naga and troll witch doctors now serve him among the stones. Gamblers who owed money in Booty Bay, once thought to have skipped town, wander here cursed and bewitched.', 'quest 621 description (Jubuwal and Aboraz, northeast of Booty Bay, mixture); quest 609 description (debtors cursed and bewitched in the ruins); quest 592 description (Yenniku with Zanzil at the Ruins of Aboraz); quest 581 (Yenniku the chief''s youngest son); DB spawns: Zanzil Zombie, Naga, Witch Doctor in 311 and 477'),
(3317, 1, 33, 17, 0, 0, 'Booty Bay', 'Booty Bay is a goblin port built into the cliffs around Blackwater Cove at the tip of the cape, entered on foot through the bleached jaws of a giant shark. It belongs to the Steamwheedle Cartel and is run by Baron Revilgaz and the Blackwater Raiders, who keep their seat atop the Salty Sailor Tavern. Ships sail from its docks as far as Ratchet. Every race is welcome so long as it brings coin and keeps the peace, and the town''s bruisers fall hard on anyone who spills blood on neutral ground. In the jungle camps they whisper that goblins sometimes drag drunken sailors onto slave boats bound for who knows where.', 'warcraft.wiki.gg/wiki/Booty_Bay (Blackwater Cove, Steamwheedle, shark jaws entrance); npc_text 7965 (servant of the Steamwheedle Cartel); quest 1181 (Revilgaz at the tavern, top floor); quest 614 (sailing from here to Ratchet); creature_text 4624 (neutral ground); quest 622 reward text (slave boat rumors); warcraft.wiki.gg/wiki/Baron_Revilgaz (pre-Cataclysm: atop the Salty Sailor Tavern)'),
(3318, 1, 33, 18, 0, 0, 'Wild Shore', 'The Wild Shore runs along the southern tip of the cape, east of Booty Bay, and the Bloodsail Buccaneers have made it their base. Their camps on the sand teem with deckhands, swashbucklers and warlocks, and their charts and written orders are kept close at hand. Just offshore ride three Bloodsail ships, the Crimson Veil, the Riptide and the Damsel''s Luck, and Fleet Master Firallon commands from below decks on the Crimson Veil. Bottles washed up on these beaches have carried pleas for help from an island farther out to sea.', 'quest 604 description (southern command post on the Wild Shore, charts and orders); quest 1036 description (Crimson Veil off the Wild Coast next to the Riptide and the Damsel''s Luck); page_text 303, 306, 307 (Bloodsail Orders); quest 594 (message in a bottle, Wild Shore); DB spawns: Bloodsail crews, Firallon 2546, gameobjects 2086, 2087 in area 43; warcraft.wiki.gg/wiki/Wild_Shore (home of the Bloodsail fleet; Booty Bay on the north side of the western point); DB: Half-Buried Bottle 2560 (drops note 4098, starts quest 594) spawns in areas 43, 297, 302, 311'),
(3319, 1, 33, 19, 0, 0, 'Jaguero Isle', 'Jaguero Isle rises from the South Seas off the cape, a wild island ruled by Skymane gorillas and stalked by jungle cats. Their master is King Mukla, a great Skymane who keeps a prisoner chained there: Princess Poobah, a tauren so far from home that the stars at night seem foreign to her. On clear days she can see the Wild Shore across the water, and she casts notes in bottles into the sea in the hope that someone will find them and come to set her free.', 'quests 594, 630 descriptions; warcraft.wiki.gg/wiki/Princess_Poobah (tauren, held by King Mukla, notes in bottles); DB spawns: Skymane Gorilla 2521, Jaguero Stalker 2522, King Mukla 1559, Princess Poobah 2634 in area 297; DB: Jaguero Stalker 2522 creature family 2 (cat)'),
(3320, 1, 33, 20, 0, 0, 'Janeiro''s Point', 'Janeiro''s Point is a rocky island off the coast near Booty Bay, crowned by a towering statue of a goblin with arms spread wide in welcome to ships making for the bay. Its only resident now is Mok''rash, a sea giant who bellows across the water day after day for Captain Hecklebury Smotts of Booty Bay to come out and fight. He mocks the captain for running out of ships to send, promises with a laugh not to kill his crew this time, and complains that the statue makes poor company.', 'warcraft.wiki.gg/wiki/Janeiro''s_Point (goblin statue welcoming ships to Booty Bay, Mok''rash); creature_text 1493 (Smotts, ships, crew, the statue); DB: Mok''rash 1493 spawn in area 312'),
(3321, 2, 33, 1, 0, 0, 'Hemet Nesingwary Jr.', 'Hemet Nesingwary Jr. is the dwarven son of the famous big game hunter Hemet Nesingwary, a renowned war hero of the Alliance. In his father''s absence, the younger Hemet leads the expedition camp in northern Stranglethorn alongside his father''s old companions. Like his father he is slow to welcome strangers, but those who prove themselves against raptors, tigers and panthers may earn a place in the great hunt, and a chance at the great and elusive beast that brought him to the Vale.', 'quest 583 description and reward text; npc_text 9218; quest 208 description (that white tiger is the reason I am here); warcraft.wiki.gg/wiki/Hemet_Nesingwary_Jr. (took over his father''s Stranglethorn camp)'),
(3322, 2, 33, 2, 0, 0, 'Baron Revilgaz', 'Baron Revilgaz rules Booty Bay from his balcony atop the Salty Sailor Tavern, a self-described humble servant of the Steamwheedle Cartel who always wants to know what a visitor can do for him. His Blackwater Raiders keep the port in goblin hands, and he leaves its day-to-day troubles to trusted subordinates such as Krazek and Kebok. Few would dare challenge him, for no one crosses Revilgaz and lives to tell of it. His private passion is the lore of the Gurubashi, and he collects ancient troll relics with real hunger.', 'npc_text 7965; quest 601 description (no one crosses Revilgaz and lives); quests 616, 611 reward texts (collection of troll artifacts); quest 189 (Kebok answers to Revilgaz); quest 4621 (Bloodsail order to kill Revilgaz and Seahorn); warcraft.wiki.gg/wiki/Baron_Revilgaz (balcony atop the Salty Sailor Tavern, delegates to Krazek and Kebok)'),
(3323, 2, 33, 3, 0, 0, 'Fleet Master Seahorn', 'Fleet Master Seahorn is the old sea dog who commands the Blackwater Raiders'' fleet of swashbucklers and stands at Baron Revilgaz''s side as his most trusted advisor. The Raiders count Booty Bay as theirs, and their rivals on these waters are the pirates of the Bloodsail Buccaneers. First Mate Crazz reports to him, and those Crazz speaks well of, who prove their dedication to the Raiders, may be trusted with missions of real importance to the fleet.', 'quest 599 reward text (fleet of swashbucklers); quest 608 description (Firallon could not sail a skiff through Crystal Lake, assassinate the leadership); creature_template 2487 subname Blackwater Raiders; warcraft.wiki.gg/wiki/Baron_Revilgaz (Seahorn his most trusted advisor); quest 595 description (our rivals, the Bloodsail Buccaneers)'),
(3324, 2, 33, 4, 0, 0, 'Fleet Master Firallon', 'Fleet Master Firallon is the human captain of the Bloodsail Buccaneers, the pirate fleet that prowls the southern coast of Stranglethorn and counts Booty Bay''s Blackwater Raiders as rivals. He commands from below decks on the Crimson Veil, anchored off the Wild Shore beside the Riptide and the Damsel''s Luck, with Captain Keelhaul and Captain Stillwater among his officers. Those who have made themselves no friends of Booty Bay find a welcome aboard his ship and a special place among the Bloodsail.', 'page_text 303, 306, 307 (Bloodsail Orders signed by Firallon); quest 1036 description and reward text; quest 4621 description and reward text (honorary admiral); warcraft.wiki.gg/wiki/Fleet_Master_Firallon (human, leads the Bloodsail around Booty Bay); page_text 303, 306 (Captain Stillwater''s crew on the Damsel''s Luck, Captain Keelhaul with the Riptide); creature 2548, 2550 faction 119 Bloodsail'),
(3325, 2, 33, 5, 0, 0, 'Colonel Kurzen', 'Colonel Kurzen was once a great and noble man, a soldier of Stormwind who led an expedition into Stranglethorn and whose men followed him with fierce loyalty. Somewhere in the jungle he fell into cruelty and madness, and his soldiers became the instruments of it. Even his enemies concede his brilliance: the rebels who broke from him call him a brilliant tactician, and they are outnumbered at least ten to one. He commands from deep within the Stockpile behind his compound.', 'quest 207 description (once a great, noble man); quest 215 reward text (fierce loyalty, corruption); quest 203 description (brilliant tactician); quest 202 description and reward text; quest 206 description; warcraft.wiki.gg/wiki/Colonel_Kurzen (human soldier from Stormwind, led an expedition to Stranglethorn)'),
(3326, 2, 33, 6, 1, 0, 'Lieutenant Doren', 'Lieutenant Doren leads the small band of rebels who broke away from Colonel Kurzen. He and his soldiers were once fiercely loyal to the colonel, and watched that devotion twist into rage as Kurzen sank into corruption. Now they hold a camp near the Duskwood road, outnumbered at least ten to one by their former comrades. Doren is a careful commander who asks discretion of those he trusts, and he trusts Sergeant Yohwa''s judgment of newcomers. He fears the rebels cannot survive alone, and pins his hopes on outsiders willing to carry the fight into the Stockpile.', 'quest 215 reward text; quest 331 reward text (Merle a brave soldier); quest 574 reward text (feared we rebels were alone); quest 202 description; creature_template 469 faction 12 (Stormwind)'),
(3327, 2, 33, 7, 0, 0, 'Mai''Zoth', 'Mai''Zoth is an ogre mage who dwells deep within the Mosh''Ogg mound in the eastern mountains of Stranglethorn. He holds the Mind''s Eye, a jewel spoken of in troll legend that makes his magic stronger still. The Darkspear remember him from the days when their tribe still lived in the jungle: vicious, and strong in magic. Those who know him say his strength is matched only by his evil.', 'quest 206 description (mind-controlling magic, corrupted Kurzen); quest 589 description (legends of the Mind''s Eye); quest 591 description (known from when the Darkspears dwelt in Stranglethorn); warcraft.wiki.gg/wiki/Mai''Zoth; quest 1240 (Kin''weelay the most powerful Darkspear witchdoctor)'),
(3328, 2, 33, 8, 2, 0, 'Nimboya', 'Nimboya is a Darkspear troll sent from distant Orgrimmar back to Stranglethorn on a grim errand. As was his people''s custom, his chief''s youngest son, Yenniku, was given to the Gurubashi of Zul''Gurub, and when the Darkspear left the jungle with Thrall the boy was lost to them. Nimboya means to find him. He hunts the Bloodscalp tribe for answers, inspecting the shrunken heads of their victims in dread of finding Yenniku among them. If the Bloodscalps have killed the boy, he swears, a curse of six hundred years will fall on the spirit of their chief, Gan''zulah.', 'quest 581 description; quest 582 description; quest 584 description; creature_template 2497 faction 126 (Darkspear)'),
(3329, 2, 33, 9, 0, 0, 'Zanzil the Outcast', 'Zanzil the Outcast is a troll witch doctor exiled by his own people, whose leaders fear his gift for bending the minds of others. He brews a mixture of jungle plants that strengthens the bodies of those who take it while suppressing their will, and his followers at the ruins of Aboraz and Jubuwal, trolls, naga and walking dead alike, are the result. In Booty Bay there are buyers who would pay well for his mixture.', 'quest 621 description and reward text; quest 588 description (controls Yenniku body and soul); warcraft.wiki.gg/wiki/Zanzil_the_Outcast (exiled, mixtures create zombies); DB: Zanzil 2534 at the Ruins of Aboraz (area 311)'),
(3330, 2, 33, 10, 0, 0, 'Captain Hecklebury Smotts', 'Captain Hecklebury Smotts once sailed a ship between Booty Bay and Ratchet and enjoyed a sterling reputation, until sea giants smashed his vessel, killed his crew and set him adrift in a lifeboat bound for Booty Bay. One of them, Gorlash, carried off his captain''s chest, whose hidden compartment held his greatest treasures, to keep as a snuffbox, and Smotts wants it back. Out on Janeiro''s Point, meanwhile, the giant Mok''rash bellows his name across the water, daring him to come out and fight.', 'quests 614/8551, 615/8553 descriptions; quest 8552 reward text (three giants, three times); creature_text 1493 (Mok''rash calls for Smotts)'),
(3331, 3, 33, 1, 0, 0, 'The Great Hunt', 'Hemet Nesingwary Jr. does not let just anyone join his expedition. A newcomer must first prove a steady hand against the beasts of the jungle under three masters. Ajeck Rouack, who learned tiger hunting from her father as a girl, starts her pupils on young cats near the camp and works up to the elder tigers. Sir S. J. Erlgadin does the same with panthers, and Hemet himself with raptors, from the common breeds to the cagey jungle stalkers. Each line ends with a beast no hunter has yet brought down: the tigress Sin''Dall, the elusive panther Bhag''thera and the treacherous raptor Tethis. Only one who has slain all three is offered the true prize: the great and elusive beast that drew Hemet to Stranglethorn in the first place.', 'quests 583, 185-188, 190-193, 194-197, 208 (descriptions and reward texts); quest_template_addon: 188, 193, 197 share ExclusiveGroup -193 leading to 208 (all three required)'),
(3332, 3, 33, 2, 0, 0, 'The Green Hills of Stranglethorn', 'Hemet Nesingwary has set down his adventures in the Vale as a novel, The Green Hills of Stranglethorn, and entrusted the manuscript to Barnil Stonepot to proofread. Then a gust of wind tore through the camp and scattered the pages across the jungle. Barnil gathered most of them, but many still lie strewn among the trees, and dreading his master''s reaction, he quietly asks for help collecting them so that the four chapters can be pieced back together. The first, he says, sets the scene and names Hemet''s hunting companions, Barnil among them, and the last is a grand finale.', 'quests 338, 339, 340, 341, 342; page_text 124-181 (the novel)'),
(3333, 3, 33, 3, 1, 0, 'Kurzen''s Rebels', 'The rebels of Lieutenant Doren''s camp fight a war they cannot win by numbers, for Colonel Kurzen is a brilliant tactician and outnumbers them at least ten to one. Sergeant Yohwa answers with Kurzen''s own covert tactics, sending raiders into the compound to the east to cut down his jungle fighters and to seize the remedies his medicine men use to heal their own and the venom fern extracts they use to poison the rebels. Brother Nimetz, convinced that the once noble colonel fell under the sway of troll magic, wants the four troll tablets hidden in the ruins of Stranglethorn transcribed and brought to him.', 'quests 203, 204, 574, 202 (Yohwa and Doren); quests 215, 200, 328, 329, 330, 331 (Thorsen and the traitor); quests 207, 205, 206 (Brother Nimetz); quest_template AllowableRaces 1101 for all'),
(3334, 3, 33, 4, 2, 0, 'The Fate of Yenniku', 'Nimboya''s search for his chief''s son begins in blood. As is the custom of the Darkspear, the chief''s youngest son Yenniku was given to the Gurubashi of Zul''Gurub, and when the tribe left the jungle with Thrall the boy was lost to them. Sent back from Orgrimmar to find him, Nimboya believes the Bloodscalp tribe has him. He sends hunters north for their tusks, and then for the shrunken heads carried by their headhunters, which he inspects one by one in dread of finding Yenniku among them. If the Bloodscalps have killed the boy, he swears, a curse of six hundred years will fall on the spirit of their chief, Gan''zulah.', 'quests 581, 582, 584, 585, 586, 588, 589, 591, 592, 593 (descriptions and reward texts); quest 1240 (Kin''weelay the most powerful Darkspear witchdoctor); quest_template AllowableRaces 690'),
(3335, 3, 33, 5, 0, 0, 'The Bloodsail Buccaneers', 'Booty Bay is run by the Blackwater Raiders, and their rivals, the Bloodsail Buccaneers, have lately been spotted all over southern Stranglethorn. First Mate Crazz, just docked and with every hand too busy with grog to help, wants a scout to check the cove north of town along the Savage Coast. The Bloodsails are looking for help of their own. ''Pretty Boy'' Duncan has heard which outsiders are no friends of Booty Bay, and sends them to Fleet Master Firallon below decks on the Crimson Veil, anchored off the Wild Shore beside the Riptide and the Damsel''s Luck, where they may find a special place among the pirates.', 'quests 595, 597, 599, 604, 608 (descriptions and reward texts); quest 608 required kills 2550, 2548, 2546; page_text 303, 306, 307 (Bloodsail Orders); quests 1036, 4621'),
(3336, 3, 33, 6, 1, 0, 'The Stone of the Tides', 'Baron Revilgaz has a hunger for the relics of the Gurubashi trolls, and he has Krazek keep an ear out for rumors of anything strange or out of place in Booty Bay and Stranglethorn. Krazek puts little stock in ghost stories, but lately sailors in the tavern have been talking about a haunted island off the coast, home to water elementals and a raving goblin ghost. If the tale is true, it may interest the baron, and Krazek would like someone to carry it to him.', 'quests 616, 578, 601, 602, 603, 610, 611 (descriptions and reward texts); page_text 286-302 (Legends of the Trolls, Volume III, Stone of the Tides); quest_template AllowableRaces 1101 for 616, 578, 610, 611');
INSERT INTO `mod_lore_codex_part` (`Entry`, `Part`, `MinState`, `MaxState`, `Body`, `Sources`) VALUES
(3301, 1, 0, 255, 'Even here the rebels were not safe. Someone in the camp passed word of Private Thorsen''s secret mission to the enemy, and a muddy note signed only with an M, found in Bookie Herod''s strongbox, led by way of the patrol rolls to the traitor: Private Merle, a soldier Doren had thought brave and true.', 'quest 215 reward text; quests 329, 330 descriptions and reward texts; quest 331 reward text'),
(3305, 1, 8, 255, 'The Farstriders of Quel''Thalas have taken an interest in these ruins. Nemeth Hawkeye, a ranger at Grom''gol, saw that the Bloodscalps here fight much like the Amani of the northern forests, and hoped their unusual magic might be turned against the Amani. A totem taken from one of their shamans named its bearer an ally of a water elemental called Naias, written in a tongue no troll could ever learn.', 'quest 9436 description and reward text; quest 9457 description; creature 17094 Nemeth Hawkeye <Farstriders> at Grom''gol'),
(3307, 1, 0, 255, 'The altar is no idle ruin. The goblin wizard Gazban, who holds the cursed Stone of the Tides, amplifies its power through it, and Archmage Ansirem Runeweaver judged that such a focus could be overpowered. Catelyn the Blade, who had heard of a sunken troll city near Gazban''s haunted island, pointed the way here.', 'quest 603 description (altar as focal point); quest 611 description (sunken troll city near that island); gameobject 2576 Altar of the Tides in area 104'),
(3309, 1, 0, 255, 'The mound guards a treasure as well. Deep in its cave the ogre mage Mai''Zoth holds the Mind''s Eye, an artifact of great power, and any who want it must take it from him by force.', 'quest 206 description (his Mind''s Eye, the artifact he uses to corrupt others); quest 589 description (a jewel of great powers); quest 591 description (held by Mai''Zoth deep within the mound)'),
(3312, 1, 3, 255, 'Once the way into Zul''Gurub lies open to outsiders, more of Rastakhan''s envoys take up their posts on the isle, each dealing with heroes of a particular calling. Jin''rokh the Breaker speaks for Mugamba, the Fist of Rastakhan, and deals with warriors and heathens, while Al''tabim the All-Seeing, an envoy of the king himself, deals with priests, mages and warlocks.', 'npc_text 7514 (Jin''rokh, envoy of Mugamba: Fist of Rastakhan; warriors and heathens); npc_text 7515 (Al''tabim, envoy of King Rastakhan; priests, mages, warlocks); mod-individual-progression ipp_aware_npcs.sql: creatures 14902-14905, 14910, 15070 use npc_ipp_zg, hidden below RequiredZulGurubProgression (default 3, the state that opens Zul''Gurub)'),
(3316, 1, 0, 255, 'Zanzil keeps a more precious captive among his followers. Yenniku, youngest son of the Darkspear chief, given to the Gurubashi long ago and lost when his tribe left the jungle, was taken by the witch doctor, who now controls him body and soul.', 'quest 581 description; quest 588 description; quest 592 description (Yenniku with Zanzil at the Ruins of Aboraz); DB: Yenniku 2530 spawned beside Zanzil 2534'),
(3318, 1, 0, 255, 'The orders kept on this shore held the Bloodsails'' secret. This is their southern command post, and from here they meant to strike at Booty Bay itself, closing in from the sea while their guns bottled up the harbor and a landing party put the town to the torch.', 'quest 597 description (wait for the signal from the southern command post); quest 604 description and reward text; page_text 303, 306, 307 (Bloodsail Orders)'),
(3318, 2, 0, 255, 'Not everything hidden on this shore belongs to the Bloodsail. A small chest on the sand holds a scroll known as Cortello''s Riddle, written in verse. It tells of an ornate, well-traveled bridge east of Deadwind Pass and south of Redridge, in the Swamp of Sorrows, where something waits underneath for whoever comes looking: a hint, or a clue.', 'quest 624 description; item 4056 Cortello''s Riddle (starts quest 624), looted from gameobject 2554 Cortello''s Riddle, spawned three times in area 43'),
(3318, 3, 0, 255, 'Beneath the bridge in the Swamp of Sorrows lay a soggy parchment bearing the next verse. It sends the seeker far over the sea to Kalimdor, east of the Barrens, into the harsh weather and dangers of Dustwallow Marsh, where another clue waits in a cave in the southwest of the marsh.', 'quest 624 reward text (the soggy parchment holds the next clue); quest 625 description, offered at once (RewardNextQuest); gameobject 2553 A Soggy Scroll ends 624 and starts 625, map 0 in the Swamp of Sorrows (area 8)'),
(3318, 4, 0, 255, 'In the Dustwallow cave a musty scroll held the last verse. It turns the hunt north to Lordaeron, a land of turmoil where soldiers toil against death, and to the coast of the Hinterlands, where the treasure lies under the water at the base of the great falls.', 'quest 625 reward text (a musty scroll); quest 626 description, offered at once (RewardNextQuest); gameobject 2555 Musty Scroll ends 625 and starts 626, map 1 in Dustwallow Marsh'),
(3318, 5, 0, 255, 'At the Overlook Cliffs in the Hinterlands, beneath the water at the foot of the great falls, Cortello''s treasure waited at last. The chest held a sturdy explorer''s knapsack, a fitting prize for someone who has followed the riddle across two continents.', 'quest 626 reward text and reward item 11324 Explorer''s Knapsack; gameobject 2556 Cortello''s Treasure ends 626, area 307 Overlook Cliffs'),
(3321, 1, 8, 255, 'These days the elder Nesingwary hunts far from the Vale. His son says he has gone off to more exotic lands in search of bigger prey, though the hunt here in Stranglethorn goes on without him.', 'npc_text 9218 (father off to more exotic locations in search of bigger prey; Burning Crusade era gossip, broadcast_text 14848); warcraft.wiki.gg/wiki/Hemet_Nesingwary (in Nagrand from The Burning Crusade, Sholazar Basin in Wrath)'),
(3321, 2, 0, 255, 'The beast is King Bangalash, a great white tiger. Hemet has had his sights on him for a long while, and the tiger has sent him crawling back to camp many times. Only a hunter who has slain Sin''Dall, Bhag''thera and Tethis is offered the chance to finish the hunt.', 'quest 208 description and request text; quest 583 reward text (a great and elusive beast)'),
(3322, 1, 0, 255, 'The Bloodsail Buccaneers want him dead. Their fleet master, Firallon, has marked Revilgaz for death together with Fleet Master Seahorn, the two who stand between the pirates and the plunder of Booty Bay.', 'page_text 303, 306 (one shot at Booty Bay, plundered loot, black spot on Revilgaz and Seahorn); quest 4621 description'),
(3323, 1, 0, 255, 'When word reached him that the Bloodsails were planning an attack on Booty Bay, Seahorn scoffed that they might as well throw themselves off the Overlook Cliffs. Still, he counted the warning a great service to his fleet, and the Blackwater Raiders gave their thanks.', 'quest 599 description and reward text'),
(3323, 2, 0, 255, 'The captured orders laid the Bloodsail plan bare, and Seahorn did not wait for the blow to fall. Firallon, he sneered, could not sail a skiff through Crystal Lake, let alone lead a fleet. Rather than send his whole fleet, he sent a few skilled fighters to the pirates'' landing spot to assassinate the Bloodsail leadership, sure their fleet would sink soon after.', 'quest 604 reward text; quest 608 description'),
(3324, 1, 0, 255, 'His orders, taken from the Wild Shore, told the whole plan. With only one shot at Booty Bay, he would have the Damsel''s Luck anchor off the southern cape to haul away the plunder, the Riptide land Keelhaul''s crew on foot from the southeast, Ironpatch''s guns pin every Blackwater ship in the harbor, and Salthoof lead a landing party to burn the town, with the black spot placed on Revilgaz and Seahorn.', 'page_text 303, 306, 307 (Bloodsail Orders signed by Firallon); quest 604 description and reward text'),
(3324, 2, 0, 255, 'Firallon has a special mission for his recruits. The powers of Booty Bay, he says, keep the Bloodsail from sailing where they like and taking what they want, and any who put a knife to both Fleet Master Seahorn and Baron Revilgaz will be named an honorary admiral of the Bloodsail navy.', 'quest 4621 description'),
(3324, 3, 0, 255, 'Fleet Master Firallon has been cut down below decks on the Crimson Veil. The captain who commanded the Bloodsail fleet from the depths of his flagship gives no more orders to the crews camped on the Wild Shore.', 'quest 608 description and reward text'),
(3325, 1, 0, 255, 'Brother Nimetz believes the colonel did not fall on his own. His study of troll legends and Skullsplitter fetishes led him to Mai''Zoth, an ogre mage of the Mosh''Ogg mound rumored to wield mind-controlling magic, and Nimetz is positive it was Mai''Zoth who corrupted Kurzen.', 'quests 207, 205 reward texts; quest 206 description'),
(3325, 2, 0, 255, 'Colonel Kurzen is dead, cut down deep within the Stockpile from which he commanded his men. The brilliant tactician who led a Stormwind expedition into the jungle, and made it an instrument of cruelty, gives no more orders.', 'quest 202 description and reward text'),
(3326, 1, 0, 255, 'Doren had sent Private Thorsen back among Kurzen''s men as a spy, a mission known only to himself, Sergeant Yohwa and Thorsen. When the secret reached the enemy he knew there must be a traitor, and the trail led to Private Merle. It pained him deeply: Merle had always been a brave soldier, and Doren had thought his heart true.', 'quest 215 description and reward text; quest 200 description; quest 331 reward text'),
(3326, 2, 0, 255, 'When proof came that Kurzen and his leaders were dead, Doren could hardly believe the reports. The colonel''s slayers had saved the rebels, he said: no menace in these jungles had Kurzen''s cruel intellect, and they could all breathe easier now that he was gone.', 'quest 202 reward text'),
(3327, 1, 0, 255, 'Brother Nimetz of the Rebel Camp is positive that it was Mai''Zoth who corrupted Colonel Kurzen. The ogre mage is rumored to bend the minds of others, the Mind''s Eye is the artifact he uses to do it, and Nimetz fears that if he lives, another Kurzen may yet rise.', 'quest 206 description and request text'),
(3327, 2, 0, 255, 'The Darkspear want the jewel for their own ends. Kin''weelay of Grom''gol, the mightiest of their witch doctors, asked the spirits of the jungle where the Mind''s Eye rests and who guards it, and he believes it is the only hope of saving Yenniku, a lost son of the tribe.', 'quest 589 description and reward text; quest 591 description; quest 1240 (Kin''weelay the most powerful Darkspear witchdoctor)'),
(3327, 3, 0, 255, 'Mai''Zoth has fallen deep within the Mosh''Ogg mound. For all his vicious strength and the jewel that sharpened his magic, the ogre mage could not stand against those who came for him, and he is gone from the world of flesh and bone.', 'quests 206, 591 reward texts'),
(3328, 1, 0, 255, 'Yenniku''s head was not among the Bloodscalps'' trophies. The truth was forced at last from the dead lips of the Bloodscalp witch doctor, appeased along with his chief: the boy was taken by Zanzil the Outcast, who controls him body and soul, so that only the most potent magic could set him free.', 'quest 584 description; quest 588 description'),
(3328, 2, 0, 255, 'That magic was found. Kin''weelay reshaped the Mind''s Eye into a soul gem, Yenniku''s soul was drawn into it, and the gem was carried back to Nimboya. He had thought the mission desperate, and he vowed that the Darkspear would remember the deed in song and etch the tale in stone so that it lives forever.', 'quest 592 description and reward text; quest 593 reward text'),
(3329, 1, 0, 255, 'His most precious captive is a Darkspear. Yenniku, youngest son of the Darkspear chief, was taken by Zanzil, who now controls the boy body and soul. Only the most potent magic, the Bloodscalp witch doctor Nezzliok sneers, could ever set him free.', 'quest 588 description'),
(3329, 2, 0, 255, 'Even Zanzil''s hold could be broken. With a soul gem that Kin''weelay of Grom''gol shaped from the Mind''s Eye, Yenniku''s soul was drawn out of his body, leaving a mindless husk, and carried away to Nimboya, freed from the will of Zanzil.', 'quest 592 description and reward text; quest 593 reward text'),
(3330, 1, 0, 255, 'Gorlash has been found and Smotts'' chest won back from him. Its return cools some of the fire in the old captain, but by his own reckoning his revenge is far from complete.', 'quests 614, 8551 reward texts'),
(3330, 2, 0, 255, 'Mok''rash is dead, and Smotts, handed back his monogrammed sash, rejoiced: by his count three sea giants have smashed his ships and killed his crews three times. After losing his first ship he bought another, named it Smotts'' Revenge and went hunting the giants, only to lose it the same way, while the giant Negolash took his cutlass. Sprogger, once his cook, survived to help track the giant down.', 'quest 8552 reward text; quest 8553 description'),
(3330, 3, 0, 255, 'Negolash, who cared less for crewmen than for wine and Sprogger''s barbecued buzzard wings, was lured to the old lifeboat with a feast, and the cutlass came home. Smotts swears his luck has turned for the better, and promises that if he ever gets a new ship, the one who won it back will sail as his honored guest.', 'quest 8554 description and reward text; creature_text 1494'),
(3331, 1, 0, 255, 'The prize is King Bangalash, the great white tiger. Hemet has had his sights on him for a long while, and the beast has sent him crawling back to camp more than once. Bring down Bangalash, he promises, and no one could doubt that the hunter''s prowess is second to none.', 'quest 208 description and request text'),
(3331, 2, 0, 255, 'King Bangalash is dead, and Hemet hailed the hunter who succeeded where others had failed. He is honored to count that hunter a comrade of his great hunting party, and swears that no one will ever doubt their expertise in hunting and tracking.', 'quest 208 reward text'),
(3332, 1, 0, 255, 'Pieced together, the four chapters tell of the camp beside the old docks, of Ajeck''s arrow felling a river crocolisk beside Barnil, of a tiger finished with a thrown axe, and of a panther crushed by a falling branch after a clumsy shot with a dwarven rifle. The tale ends with the hunters trapped on a sea cliff by lashtail raptors, saved only when a great white tiger charged in from the side and scattered the pack. Barnil expects to see the book in libraries throughout the world.', 'page_text 124-181 (the novel); quests 339, 342 descriptions; quest 338 reward text'),
(3333, 1, 0, 255, 'Private Thorsen had been charged by Doren to rejoin Kurzen''s men as a spy, a mission known only to Doren, Yohwa and Thorsen himself. Yet Kurzen''s men fell on him when he went to rejoin them, and he had to be rescued. If such a secret reached the enemy, Doren reasoned, there must be a traitor in the camp.', 'quest 215 description and reward text; quest 200 description; creature_text 738'),
(3333, 2, 0, 255, 'Bookie Herod, Kurzen''s logistics officer and Thorsen''s contact, kept his records in the compound''s only two-story house. A small brass key hidden in a ledger''s binding opened his strongbox in the Stockpile, and inside lay a muddy note tracking Thorsen''s every move, signed only with an M. The patrol rolls did the rest: the traitor was Private Merle.', 'quests 200, 328, 329, 330 descriptions and reward texts; quest 331 reward text'),
(3333, 3, 0, 255, 'With his jungle fighters thinned and his special forces broken in the Stockpile, Doren dared to hope, and sent champions into the cavern to face the colonel himself. They came back with Kurzen''s head. The rebels had been saved, Doren said, and could all breathe easier now that he was gone.', 'quest 574 description and reward text; quest 202 description and reward text'),
(3333, 4, 0, 255, 'Brother Nimetz, studying the tablets and the fetishes of the Skullsplitter witch doctors, found the cause he sought. An ogre mage named Mai''Zoth dwells in the Mosh''Ogg mound, rumored to wield mind-controlling magic, and Nimetz is positive he corrupted Kurzen. If Mai''Zoth lives, he warns, another Kurzen may surface.', 'quests 207, 205 reward texts; quest 206 description'),
(3333, 5, 0, 255, 'Mai''Zoth was slain and his Mind''s Eye, the artifact he used to corrupt others, carried back to the Rebel Camp. Nimetz means to study it and learn whether it can be turned to good. If not, it must be destroyed.', 'quest 206 reward text'),
(3334, 1, 0, 255, 'Yenniku''s head was not among them, and Nimboya thanked the Great Serpent for it. Only the Bloodscalp chief Gan''zulah and his witch doctor Nezzliok the Dire know the truth, and they will not speak freely, so Nimboya means to force it from their dead lips: their heads are to be taken from deep within Zul''Kunda and placed in the bubbling cauldron at Grom''gol.', 'quest 582 reward text; quest 584 description'),
(3334, 2, 0, 255, 'In the cauldron the heads spoke, and demanded appeasement. Nezzliok wanted three trophy skulls stolen from the Skullsplitters, from Balia''mah, Ziata''jai and Zul''Mamwe, to serve him as slaves in the Nether; Gan''zulah wanted the shattered armor of the Skullsplitter chief Ana''thek the Cruel. Appeased, Nezzliok told the truth: Yenniku was taken by Zanzil the Outcast, who controls him body and soul.', 'quests 585, 586 descriptions and reward texts; quest 588 description'),
(3334, 3, 0, 255, 'Kin''weelay of Grom''gol, the mightiest Darkspear witch doctor, saw a faint hope. Legends spoke of a jewel called the Mind''s Eye, and singing shards cut from the basilisks of the Crystalvein Mine could bend it to his will. The spirits of the jungle told him it was held by the ogre mage Mai''Zoth. Once the Eye was taken, Kin''weelay reshaped it into a soul gem able to stun Yenniku and entrap his soul.', 'quest 588 reward text; quests 589, 591 descriptions and reward texts; quest 592 description; quest 1240 (most powerful witchdoctor of the Darkspear)'),
(3334, 4, 0, 255, 'At the Ruins of Aboraz the gem struck Yenniku dumb, and placed upon his forehead it drew in his soul, leaving his body behind as a mindless husk. The filled gem was carried back to Nimboya, who had thought the mission desperate. Yenniku was freed from the will of Zanzil, and Nimboya vowed that the Darkspear would sing of his rescuer and etch the tale in stone so that it would live forever.', 'quest 592 description and reward text; quest 593 request and reward texts; creature_text 2530'),
(3335, 1, 0, 255, 'In a skiff hidden in the cove lay a map of Booty Bay marked with an X on that very spot, with orders to make camp, keep quiet, kill anyone who came near and wait for a signal from the southern command post before attacking. The Bloodsails were planning an attack on Booty Bay, and Crazz wanted Fleet Master Seahorn told at once.', 'quest 595 reward text; quest 597 description; quest 599 description'),
(3335, 2, 0, 255, 'Seahorn scoffed, but had the southern command post on the Wild Shore raided for its charts and orders, and they laid bare Firallon''s plan: with only one shot at Booty Bay, ships would close in from the sea, guns would seal the harbor, and a landing party would burn the town, with the black spot placed on Revilgaz and Seahorn.', 'quest 599 reward text; quest 604 description and reward text; page_text 303, 306, 307 (Bloodsail Orders)'),
(3335, 3, 0, 255, 'Seahorn struck first. Rather than send his whole fleet, he sent a small band of skilled fighters out to the pirates'' landing spot to assassinate the Bloodsail leadership, and Fleet Master Firallon and his captains Keelhaul and Stillwater were slain. It was, the old sea dog declared, a great day for the Blackwater Raiders.', 'quest 608 description and reward text; quest 608 required kills 2550, 2548, 2546'),
(3335, 4, 0, 255, 'Those who sailed with the Bloodsails were given a darker errand. Firallon asked them to put a knife to both Seahorn and Revilgaz, for Booty Bay''s power keeps the pirates from plundering as they please. Those who did it were hailed as honorary admirals of the Bloodsail navy, given a hat like no other, and toasted with three cheers.', 'quest 1036 reward text; quest 4621 description and reward text; creature_text 2546'),
(3336, 1, 0, 255, 'Revilgaz recognized the tale. He had first read of the Stone of the Tides in a troll legend, in a book the Stormwind Library can still provide, and if a goblin mage and water elementals truly haunt the island, he suspects the goblin wizard Gazban has discovered the Stone. He wants it for his collection.', 'quest 616 reward text; quest 578 description (scrip for the Stormwind Library, could Gazban have discovered the Stone)'),
(3336, 2, 0, 255, 'The haunting was real. Troll legend tells why the Stone is no simple prize. A blue stone shot through with milky strands, it gave Gurubashi warriors command over water, and each bearer was honored at Zul''Gurub as Tidebearer, yet the Stone cursed him, and he slowly faded from existence until he walked into the sea. Before it could be taken, Revilgaz judged, the curse must be defeated, and that was wizards'' business.', 'quest 578 reward text (the stories were true, the curse needs a wizard); quest 601 description (the curse makes its bearer fade in and out of existence); page_text 286-302 (Legends of the Trolls, Volume III, Stone of the Tides)'),
(3336, 3, 0, 255, 'To break the curse, Revilgaz sent bracers from the island''s water elementals to Archmage Ansirem Runeweaver of Dalaran, who had written that very legend down himself. Ansirem found that the mage holding the Stone amplifies its power through an altar, which an ancient troll dagger could overpower. He had given the dagger to his daughter Catelyn, who ran off to Booty Bay to become a pirate, and she had lost it in a knife fight to one of the Bloodsail Buccaneers.', 'quest 601 description and reward text; quest 602 reward text; page_text 286 (by the hand of Archmage Ansirem Runeweaver); quest 603 description and reward text'),
(3336, 4, 0, 255, 'The thief was ''Pretty Boy'' Duncan, who had knocked Catelyn senseless with a blow to the head rather than best her blade to blade. He was made to give the dagger up, and Catelyn, her blade restored, allowed that its finder was not so wet behind the ears after all.', 'quest 610 description, request and reward texts'),
(3336, 5, 0, 255, 'Catelyn had heard of a sunken troll city near the haunted island. There, in the Vile Reef, her blade overcame the Altar of the Tides, Gazban fell, and the Stone of the Tides was carried back to Booty Bay, where Revilgaz had already cleared a space and bought a fine stand for it. It holds a place of prominence in his collection, a tide seemingly trapped within its surface.', 'quest 611 description, request and reward texts');
